}
@Composable internal fun HistoryScreen(store:AppStore,onWeek:(SavedWeek)->Unit,back:()->Unit){val weeks=store.loadWeeks();val recent=weeks.take(4);val total=recent.sumOf{it.takeHomeCents};val average=if(recent.isEmpty())0L else total/recent.size;val hourlyWeeks=recent.filter{(it.hours?:0.0)>0.0};val totalHours=hourlyWeeks.sumOf{it.hours?:0.0};val hourly=if(totalHours>0)(hourlyWeeks.sumOf{it.takeHomeCents}.toDouble()/totalHours).roundToLong()else null;SimpleScreen(stringResource(R.string.history),back){if(weeks.isNotEmpty()){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp)){Box(Modifier.weight(1f)){HistoryMetric(stringResource(R.string.last_four_weeks),total)};Box(Modifier.weight(1f)){HistoryMetric(stringResource(R.string.average_week),average)}};if(hourly!=null)HistoryMetric(stringResource(R.string.average_hourly),hourly,stringResource(R.string.per_hour_suffix))};weeks.take(12).forEach{week->Row(Modifier.fillMaxWidth().clickable{onWeek(week)}.padding(vertical=16.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(weekRange(week.startMillis, store.appLanguage),fontSize=19.sp,fontWeight=FontWeight.Bold,color=Ink,fontFamily=AppFontFamily);Text(formatCents(week.takeHomeCents, store.appLanguage),fontSize=20.sp,fontWeight=FontWeight.ExtraBold,color=Ink,fontFamily=AppFontFamily)}}}}
