@Composable internal fun CompareScreen(store:AppStore,services:Long,cashTips:Long,cardTips:Long,supplies:Long,back:()->Unit){val context=LocalContext.current;val feeRate=BigDecimal(store.cardFeeBasisPoints).movePointLeft(4);val cardShare=BigDecimal(store.servicesOnCardBasisPoints).movePointLeft(4);val cut=BigDecimal(store.commissionCutBasisPoints).movePointLeft(4);val booth=MoneyMath.boothTakeHome(services,cashTips,cardTips,supplies,store.weeklyRentCents,store.extraFeesCents,feeRate,cardShare);val commission=MoneyMath.commissionTakeHome(services,cashTips,cardTips,supplies,cut,store.tipOwner,store.workerPaysCardFees,store.extraFeesCents,feeRate,cardShare);val hybrid=MoneyMath.hybridTakeHome(services,cashTips,cardTips,supplies,store.weeklyRentCents,cut,store.tipOwner,store.workerPaysCardFees,store.extraFeesCents,feeRate,cardShare);val winner=maxOf(booth,commission,hybrid);SimpleScreen(stringResource(R.string.compare),back){Text(compareVerdict(context,booth,commission,hybrid),color=Pink,fontSize=20.sp,fontWeight=FontWeight.ExtraBold,fontFamily=AppFontFamily);CompareRow(stringResource(R.string.compare_booth),booth,booth==winner);CompareRow(stringResource(R.string.compare_commission),commission,commission==winner);CompareRow(stringResource(R.string.compare_hybrid),hybrid,hybrid==winner)}}
internal fun compareVerdict(context: Context, booth: Long, commission: Long, hybrid: Long): String {
    val scores = listOf("booth" to booth, "commission" to commission, "hybrid" to hybrid)
    val best = scores.maxOf { it.second }
    val winners = scores.filter { it.second == best }
    if (winners.size != 1) return context.getString(R.string.compare_verdict_tie)
    val second = scores.filter { it.first != winners[0].first }.maxOf { it.second }
    val extra = best - second
    if (extra <= 0) return context.getString(R.string.compare_verdict_tie)
    val amount = formatCents(extra, appLanguage(context))
    return when (winners[0].first) {
        "booth" -> context.getString(R.string.compare_verdict_booth, amount)
        "commission" -> context.getString(R.string.compare_verdict_commission, amount)
        else -> context.getString(R.string.compare_verdict_hybrid, amount)
    }
}
